"""Tests for the app config."""

from pathlib import Path

from foca.config.config_parser import ConfigParser

CONFIG_FILE = Path(__file__).parents[1] / "cloud_registry" / "config.yaml"
CUSTOM_CONFIG_MODEL = "cloud_registry.service_models.custom_config.CustomConfig"


def test_config_overlay(tmp_path, monkeypatch):
    """A config overlay, as generated by the Helm chart, overrides the base
    config and keeps all other values.
    """
    overlay = tmp_path / "overlay.yaml"
    overlay.write_text(
        "custom:\n"
        "  endpoints:\n"
        "    service:\n"
        "      url_prefix: https\n"
        "      external_host: registry.example.org\n"
        "      external_port: 443\n"
    )
    monkeypatch.setenv("FOCA_CONFIG_OVERLAY", str(overlay))
    config = ConfigParser(
        config_file=CONFIG_FILE,
        custom_config_model=CUSTOM_CONFIG_MODEL,
        format_logs=False,
    ).config
    service = config.custom.endpoints.service
    assert (service.url_prefix, service.external_host, service.external_port) == (
        "https",
        "registry.example.org",
        443,
    )
    assert config.custom.endpoints.service_info.id
    assert config.db.host == "mongodb"
